import os
import stat
import hashlib
import hmac
from typing import Optional, Tuple


class SecureFileVault:
    """Secure file storage with integrity verification.
    Uses O_NOFOLLOW to prevent symlink attacks at open time."""

    def __init__(self, vault_root: str, secret_key: bytes):
        # Resolve once at init to establish canonical root
        self.vault_root = os.path.realpath(vault_root)
        self.secret_key = secret_key
        os.makedirs(self.vault_root, mode=0o700, exist_ok=True)

    def _compute_mac(self, filename: str, data: bytes) -> str:
        # Bind the filename into the MAC to prevent content-swap/relocation
        # attacks where two stored files (and their MACs) are exchanged.
        h = hmac.new(self.secret_key, digestmod=hashlib.sha256)
        fname_bytes = filename.encode('utf-8')
        # Length-prefix the filename so it is unambiguously separated from data.
        h.update(len(fname_bytes).to_bytes(8, 'big'))
        h.update(fname_bytes)
        h.update(data)
        return h.hexdigest()

    @staticmethod
    def _write_all(fd: int, data: bytes) -> None:
        """Write all bytes, handling partial os.write() results."""
        view = memoryview(data)
        total = 0
        while total < len(view):
            written = os.write(fd, view[total:])
            if written <= 0:
                raise OSError("Short write to file descriptor")
            total += written

    def _validate_filename(self, filename: str) -> bool:
        """Strict filename validation - alphanumeric, hyphens, dots only."""
        if not filename or len(filename) > 128:
            return False
        allowed = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_.')
        if not all(c in allowed for c in filename):
            return False
        if filename.startswith('.') or '..' in filename:
            return False
        return True

    def _safe_open_read(self, filepath: str) -> Optional[int]:
        """Open file for reading with O_NOFOLLOW to reject symlinks atomically.
        This prevents TOCTOU attacks by combining the check and open."""
        try:
            fd = os.open(filepath, os.O_RDONLY | os.O_NOFOLLOW)
            # Verify ownership after open (on the actual opened fd)
            st = os.fstat(fd)
            if st.st_uid != os.getuid():
                os.close(fd)
                return None
            if st.st_mode & (stat.S_IROTH | stat.S_IWOTH):
                os.close(fd)
                return None
            return fd
        except OSError:
            return None

    def _safe_open_write(self, filepath: str) -> Optional[int]:
        """Open file for writing with O_NOFOLLOW | O_CREAT | O_EXCL or O_TRUNC."""
        try:
            flags = os.O_WRONLY | os.O_NOFOLLOW | os.O_CREAT | os.O_TRUNC
            fd = os.open(filepath, flags, 0o600)
            return fd
        except OSError:
            return None

    def _build_filepath(self, filename: str) -> Optional[str]:
        """Build and validate the target filepath.
        Note: We don't use realpath here because O_NOFOLLOW at open time
        provides atomic symlink protection without TOCTOU window."""
        # Simple join - filename is already validated to have no path separators
        # or traversal sequences by _validate_filename
        candidate = self.vault_root + os.sep + filename
        # Normalize (collapse redundant separators) without resolving symlinks
        candidate = os.path.normpath(candidate)
        # Verify prefix containment on the normalized (but not resolved) path
        if not candidate.startswith(self.vault_root + os.sep):
            return None
        return candidate

    def store_file(self, filename: str, data: bytes) -> Tuple[bool, str]:
        """Store data securely in the vault with MAC."""
        if not self._validate_filename(filename):
            return False, "Invalid filename"

        filepath = self._build_filepath(filename)
        if filepath is None:
            return False, "Path validation failed"

        mac = self._compute_mac(filename, data)

        # Remove existing symlink if someone placed one (defense in depth)
        try:
            if os.path.islink(filepath):
                os.unlink(filepath)
        except OSError:
            pass

        fd = self._safe_open_write(filepath)
        if fd is None:
            return False, "Cannot open file for writing"
        try:
            self._write_all(fd, data)
        except OSError:
            os.close(fd)
            try:
                os.unlink(filepath)
            except OSError:
                pass
            return False, "Failed to write data"
        else:
            os.close(fd)

        # Write MAC file
        mac_path = filepath + '.mac'
        try:
            if os.path.islink(mac_path):
                os.unlink(mac_path)
        except OSError:
            pass

        mac_fd = self._safe_open_write(mac_path)
        if mac_fd is None:
            # Cleanup data file on failure
            try:
                os.unlink(filepath)
            except OSError:
                pass
            return False, "Cannot write MAC file"
        try:
            self._write_all(mac_fd, mac.encode('ascii'))
        except OSError:
            os.close(mac_fd)
            try:
                os.unlink(mac_path)
            except OSError:
                pass
            try:
                os.unlink(filepath)
            except OSError:
                pass
            return False, "Failed to write MAC file"
        else:
            os.close(mac_fd)

        return True, mac

    def read_file(self, filename: str) -> Tuple[bool, bytes]:
        """Read and verify file from vault.
        Uses O_NOFOLLOW for atomic symlink rejection."""
        if not self._validate_filename(filename):
            return False, b"Invalid filename"

        filepath = self._build_filepath(filename)
        if filepath is None:
            return False, b"Path validation failed"

        # Open with O_NOFOLLOW - atomically rejects symlinks
        fd = self._safe_open_read(filepath)
        if fd is None:
            return False, b"Cannot open file (missing, symlink, or bad permissions)"

        try:
            data = b''
            while True:
                chunk = os.read(fd, 65536)
                if not chunk:
                    break
                data += chunk
        finally:
            os.close(fd)

        # Read and verify MAC
        mac_path = filepath + '.mac'
        mac_fd = self._safe_open_read(mac_path)
        if mac_fd is None:
            return False, b"MAC file missing or inaccessible"

        try:
            mac_data = os.read(mac_fd, 128).decode('ascii').strip()
        finally:
            os.close(mac_fd)

        expected_mac = self._compute_mac(filename, data)
        if not hmac.compare_digest(expected_mac, mac_data):
            return False, b"Integrity check failed"

        return True, data

    def delete_file(self, filename: str) -> Tuple[bool, str]:
        """Securely delete a file from the vault."""
        if not self._validate_filename(filename):
            return False, "Invalid filename"

        filepath = self._build_filepath(filename)
        if filepath is None:
            return False, "Path validation failed"

        # Reject if it's a symlink
        if os.path.islink(filepath):
            return False, "Refusing to delete symlink"

        try:
            # Open with O_NOFOLLOW to ensure we're overwriting the real file
            fd = os.open(filepath, os.O_WRONLY | os.O_NOFOLLOW)
            try:
                size = os.fstat(fd).st_size
                self._write_all(fd, os.urandom(size))
            finally:
                os.close(fd)
            os.unlink(filepath)

            mac_path = filepath + '.mac'
            if os.path.isfile(mac_path) and not os.path.islink(mac_path):
                os.unlink(mac_path)
            return True, "Deleted"
        except OSError as e:
            return False, str(e)


def create_vault(root_dir: str) -> SecureFileVault:
    """Factory function to create a vault instance."""
    secret = os.environ.get('VAULT_SECRET_KEY', '')
    if len(secret) < 32:
        raise ValueError("VAULT_SECRET_KEY must be at least 32 characters")
    return SecureFileVault(root_dir, secret.encode('utf-8'))
